{
  "obligations": [
    {
      "text": "The ESP32 must publish a retained MQTT payload with 'liters', 'pct', 'raw_mm', and 'rssi' fields every five minutes, with a median-of-7 smoothing and a watchdog to flag sensor anomalies.",
      "source_ids": ["m02", "m04", "m08"]
    },
    {
      "text": "The low-water alert threshold must remain at 15% and the near-full alert at 98% unless explicitly approved by the user, with the 98% alert retired due to the tank's overflow pipe.",
      "source_ids": ["m05", "m15", "m16"]
    },
    {
      "text": "The frost-watch rule must activate when the DS18B20 reads 3 °C or below, switching to 60-second sampling and adding 'frost_warning=true' to the payload, with a 4 °C hysteresis to avoid false triggers.",
      "source_ids": ["m17", "m18"]
    },
    {
      "text": "The weekly usage report must be emailed to the user on Sundays at 18:00 in plain text with a CSV attachment of the week's samples, with consumption expressed in kiloliters with one decimal place.",
      "source_ids": ["m21", "m22"]
    },
    {
      "text": "The dashboard must suppress buzzer and banner alerts in demo mode, while continuing to log all alerts exactly as usual.",
      "source_ids": ["m23", "m24"]
    },
    {
      "text": "The firmware must include the 15% and 98% thresholds in a single config block at the top for clarity and consistency.",
      "source_ids": ["m08", "m16"]
    },
    {
      "text": "The 25 cm clearance note from the sensor datasheet is retained as a quote but not a constraint for this project, with the 11 cm clearance used as tested.",
      "source_ids": ["m09", "m10"]
    },
    {
      "text": "The firmware must allow the user to adjust the smoothing window size when needed, but not below 3 readings.",
      "source_ids": ["m19"]
    },
    {
      "text": "The system must buffer readings on the device for up to 24 hours if the broker is unreachable, and backfill them when reconnected without requiring user approval.",
      "source_ids": ["m21"]
    }
  ]
}
